zf=zipfile.ZipFile('/root/clinic_intake_ready.hwpx')
for name in zf.namelist():
    if name.endswith('.xml'):
        txt=zf.read(name).decode('utf-8')
        m=re.findall(r'\{\{.*?\}\}', txt)
        if m:
            print('PLACEHOLDERS', name, m)
